@Component("prediction-handler")
@ProcessingGroup("prediction-processing-group")
public class PredictionEventHandler {
	
	// core constructor
	PredictionEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreatePredictionEvent
     */
    @EventHandler
    public void handle( CreatePredictionEvent event) {
        entityManager.persist(new Prediction(event.getPredictionId(), event.getReferenceKey(), event.getPredictedAt(), event.getScore(), event.getEndpoint(), event.getModelVersion(), event.getDataset()));
    }

    /*
     * @param	event UpdatePredictionEvent
     */
    @EventHandler
    public Prediction handle( UpdatePredictionEvent event) {
    	entityManager.merge(new Prediction(event.getPredictionId(), event.getReferenceKey(), event.getPredictedAt(), event.getScore(), event.getEndpoint(), event.getModelVersion(), event.getDataset()));
    }
    
    /*
     * @param	event DeletePredictionEvent
     */
    @EventHandler
    public void on( DeletePredictionEvent event) {
    	Prediction entity = new Prediction();
   
    	// ------------------------------------------
    	// apply the PredictionId
    	// ------------------------------------------
    	entity.setPredictionId( event.getPredictionId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final PredictionRepository predictionEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(PredictionEventHandler.class.getName());

}
